using namespace std;

const string fir[10] = {"+------+",
                        "|      |",
                        "| /  \\ |",
                        "|      |",
                        "| +--+ |",
                        "| |  | |",
                        "| |  | |",
                        "+-+--+-+"};

int n;
string ans[1000];

void change(int x) {
    string pre = "+";
    for (int i=1; i<=(1<<x)-1; ++i) {
        pre+="-";
    }
    string fix="";
    for (int i=1; i<=(1<<x)-1; ++i) {
        fix+="-";
    }
    fix+="+";
    ans[0] = pre + ans[0] + fix;
    for (int i=1; i<(1<<(1+x)); ++i) {
        pre = "|";
        for (int j=1; j<=(1<<x)-1; ++j) {
            pre+=" ";
        }
        fix="";
        for (int j=1; j<=(1<<x)-1; ++j) {
            fix+=" ";
        }
        fix+="|";
        ans[i] = pre + ans[i] +fix;
    }
    int sp = 0;
    for (int i=(1<<(1+x)); i<(1<<(2+x)); ++i) {
        if (i==(1<<(2+x))-1) {
            ans[i] = "+";
            for (int j=1; j<=(1<<(2+x))-2; ++j) ans[i]+="-";
            ans[i] += "+";
        } else if (i==(1<<(1+x)) || i==(1<<(2+x))-2) {
            ans[i] = "|";
            for (int j=1; j<=(1<<(2+x))-2; ++j) ans[i]+=" ";
            ans[i] += "|";
        } else {
            ans[i] = "|";
            ++sp;
            for (int j=1; j<=sp; ++j) {
                ans[i] += " ";
            }
            ans[i] += "/";
            for (int j=sp+3; j<=(1<<(2+x))-sp-2; ++j) {
                ans[i] +=" ";
            }
            ans[i] += "\\";
            for (int j=1; j<=sp; ++j) {
                ans[i] += " ";
            }
            ans[i]+="|";
        }
    }
}

void doit() {
    scanf("%d", &n);
    for (int i=7; i>=0; --i) {
        ans[i] = fir[8-i-1];
    }
    for (int i=2; i<=n; ++i) {
        change(i);
    }
    for (int i=(1<<(2+n))-1; i>=0; --i) {
        printf("%s\n", ans[i].c_str());
    }
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) doit();
	return 0;
}

