#include <cstdio>
using namespace std;
int t,n;
char a[600][600];

void outside(int x,int y,int z)
{
     int i,j;
     a[x][y]='+'; a[x][y+z-1]='+'; a[x+z-1][y]='+'; a[x+z-1][y+z-1]='+';
     for (i=y+1;i<=y+z-2;i++)
     {
         a[x][i]='-';
         a[x+z-1][i]='-';
     }
     for (i=x+1;i<=x+z-2;i++)
     {
         a[i][y]='|';
         a[i][y+z-1]='|';
     }
     return;
}

void work(int x,int y,int z)
{
     int i,j,k;
     outside(x,y,z);
     i=x+2; j=y-2+z/2; k=j+3;
     while (j!=y+1)
     {
           a[i][j]='/';
           a[i][k]='\\';
           i++; j--; k++;
     }
     return;
}

int main()
{
    int i,j,k,l,q;
    scanf("%d",&t);
    while (t--)
    {
          scanf("%d",&n);
          k=4;
          for (i=1;i<=n;i++) k*=2;
          for (i=1;i<=k;i++)
              for (j=1;j<=k;j++)
                  a[i][j]=' ';
          i=1; j=1; q=k;
          for (l=1;l<=n;l++)
          {
              work(i,j,q);
              i=(i+k-1)/2+1;
              j+=q/4;
              q/=2;
          }
          outside(i,j,q);
          for (i=1;i<=k;i++)
          {
              for (j=1;j<=k;j++)
                  printf("%c",a[i][j]);
              printf("\n");
          }
          printf("\n");
    }
    return 0;
}

#include <stdio.h>

char a[512][512];

void creat(int x, int y, int n)
{
    int i, j, count;
    for (i = x, count = 1 << (2 + n); i < count + x; i++)
    for (j = y; j < count + y; j++)
    {
        if ((i == x)||(i == x + count - 1))
        {
            if ((j == y)||(j == y + count - 1)) a[i][j] = '+';
            else a[i][j] = '-';
        }
        else if ((j == y)||(j == y + count - 1)) a[i][j] = '|';
        else a[i][j] = ' ';
    }
    if (n > 0)
    {
        for (i = 0; i < (count >> 1) - 3; i++)
        {
            a[x + (count >> 1) - 2 - i][y + 2 + i] = '/';
            a[x + (count >> 1) - 2 - i][y + count - 3 - i] = '\\';
        }
        creat(x + (1 << (1 + n)), y + (1 << n), n - 1);
    }
}

void check(int n)
{
    int x, y, i, j;
    for (i = 7, x = 0, y = 0; i > n; i--)
    {
        x += (1 << (i + 1));
        y += (1 << i);
    }
    for (i = x; i < 512; i++)
    {
        for (j = y; j < y + (1 << (n + 2)); j++) putchar(a[i][j]);
        putchar('\n');
    }
    putchar('\n');
}

int main()
{
    int t, n;

    creat(0, 0, 7);
    for (scanf("%d", &t); t > 0; t--)
    {
        scanf("%d", &n);
        check(n);
    }
    return 0;
}

