#include <stdio.h>

char a[513][513]={0};

long vj(long x,long y,long w){
   // printf("%ld %ld %ld\n",x,y,w);
    long i,j,v=w-1;
    for(i=1;i<v;i++){a[x][y+i]=a[x+v][y+i]='-';a[x+i][y]=a[x+i][y+v]='|';}
    a[x][y]=a[x][y+v]=a[x+v][y]=a[x+v][y+v]='+';
    if(w<8) return 0;
    for(i=2;1;i++){
        j=(w>>1)-i;
        a[x+i][y+j]='/';
        a[x+i][y+(v&~j)]='\\';
        if(j==2)break;
    }
    return vj(x+(w>>1),y+(w>>2),(w>>1));
}

void init(void){
    long i,j;
    for(i=0;i<512;i++)for(j=0;j<512;j++)a[i][j]=' ';
    vj(0,0,512);
}

long printy(long ne){
    long sx,sy,sw,i,j;
    sx=512-(4<<ne);
    sy=sx>>1;
    sw=4<<ne;
   // printf("ne=%ld sx=%ld sy=%ld sw=%ld\n",ne,sx,sy,sw);
    for(i=sx;i<sx+sw;i++){
        for(j=sy;j<sy+sw;j++){
            printf("%c",a[i][j]);
        }
        printf("\n");
    }
    printf("\n");
    return 0;
}

int main(void){
    long T,I,xx;
    init();
    scanf("%ld",&T);
    for(I=0;I<T;I++){
        scanf("%ld",&xx);
        printy(xx);
    }
    return 0;
}

