using namespace std;
char G[1100][1100];
int X[10],Y[10],Len[10];
void Build(int n,int x,int y)
{
    if (n==0) return;
    X[n]=x;Y[n]=y;
    int L=(1<<(2+n)),i,j;
    Len[n]=L;
    for (i=0;i<L;i++)
        for (j=0;j<L;j++)
            G[i+x][j+y]=' ';
    for (i=1;i<L-1;i++)
        G[i+x][y]=G[i+x][y+L-1]='|';
    for (j=1;j<L-1;j++)
        G[x][j+y]=G[x+L-1][j+y]='-';
    G[x][y]=G[x+L-1][y]=G[x][y+L-1]=G[x+L-1][y+L-1]='+';
    for (i=L/2-2;i>1;i--)
    {
        G[x+i][y+L/2-i]='/';
        G[x+i][y+L-1-(L/2-i)]=92;
    }
    for (i=L/2+1;i<L-1;i++)
        G[x+i][y+L/4]=G[x+i][y+L-1-L/4]='|';
    for (j=L/4+1;j<L-1-L/4;j++)
        G[x+L/2][y+j]='-';
    G[x+L/2][y+L-1-L/4]=G[x+L-1][y+L-1-L/4]=G[x+L/2][y+L/4]=G[x+L-1][y+L/4]='+';
    Build(n-1,x+L/2,y+L/4);
}
void Print(int n)
{
    int i,j;
    for (i=0;i<Len[n];i++)
    {
        for (j=0;j<Len[n];j++)
            putchar(G[X[n]+i][Y[n]+j]);
        puts("");
    }
    puts("");
}
