using namespace std;

void draw(int line, int l)
{
    double length = 8*pow(2,l-1);

    if(line==0)
    {
            for(int i=0; i<length; i++)
            {
                    if(i==0 || i == length-1)
                            cout<<'+';
                    else 
                            cout<<'-';        
            }
            return ;
    }


    if(line==length-1)
    {
            for(int i=0; i<length; i++)
            {
                    if(l != 1)
                    {     
                        if(i==0 || i == length-1)
                                cout<<'+';
                        else if(i==pow(2,l))
                        {
                             draw(line-length/2, l-1);
                             i = i+length/2 -1;
                        }
                        else
                                cout<<'-';      
                    } else {
                        if(i==0 || i == length-1)
                                cout<<'+';
                        else if(i==2 || i==5)
                                cout<<'+';
                        else
                                cout<<'-';      
                    }
            }           
            return ;       
    }

    if(line == 1 || line == length/2 -1)
    {
            for(int i=0; i<length; i++)
            {
                    if(i==0 || i == length-1)
                            cout<<'|';
                    else 
                            cout<<' ';        
            }
            return ;           
    }

    if(line < length/2 -1 )
    {
            int il = length/2 - line;
            int ir = length/2 + line - 1;
            for(int i=0; i<length; i++)
            {
                    if(i==0 || i == length-1)
                            cout<<'|';
                    else if(i==il)
                            cout<<'/';
                    else if(i==ir)
                            cout<<'\\';
                    else 
                            cout<<' ';        
            }
            return ;           
    }

       if(line == length/2)
    {
            for(int i=0; i<length; i++)
            {
                    if(l != 1)
                    {     
                        if(i==0 || i == length-1)
                                cout<<'|';
                        else if(i==pow(2,l))
                        {
                             draw(line-length/2, l-1);
                             i = i+length/2 -1;
                        }
                        else
                                cout<<' ';      
                    } else {
                        if(i==0 || i == length-1)
                                cout<<'|';
                        else if(i==2 || i==5)
                                cout<<'+';
                        else if(i>2 && i<5)
                                cout<<'-';
                        else
                                cout<<' ';      
                    }
            }           
            return ;       
    }

    if(line > length/2 )
    {
            for(int i=0; i<length; i++)
            {
                    if(l != 1)
                    {     
                        if(i==0 || i == length-1)
                                cout<<'|';
                        else if(i==pow(2,l))
                        {
                             draw(line-length/2, l-1);
                             i = i+length/2 -1;
                        }
                        else
                                cout<<' ';      
                    } else {
                        if(i==0 || i == length-1)
                                cout<<'|';
                        else if(i==2 || i==5)
                                cout<<'|';
                        else
                                cout<<' ';      
                    }   
            }
            return ;
    }
}


