const int b[12] = {1, 1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024};

int build(int n, int x, int y)
{
    int i;
    if(!n) 
    {
    for(i = 0; i < b[n] * 4; i++)
    {
          s[x][y + i] = '-';
          s[x + i][y] = '|';
          s[x + b[n] * 4 - 1][y + i] = '-';
          s[x + i][y + b[n] * 4  - 1] = '|';
    }
    s[x][y] = s[x +b[n] * 4 - 1][y] = s[x][y + b[n] * 4 - 1] = s[x + b[n] * 4 - 1][y + b[n] * 4 - 1] = '+';
           return 0;
    }

    for(i = 0; i < b[n] * 8; i++)
    {
          s[x][y + i] = '-';
          s[x + i][y] = '|';
          s[x + b[n] * 8 - 1][y + i] = '-';
          s[x + i][y + b[n] * 8  - 1] = '|';
    }
    for(i = x + 2; i < x - 1+ b[n] * 4; i++)
    {
          s[i][y + b[n] * 4 - (i - x - 2)- 2] = '/';
          s[i][y + b[n] * 4 + (i - x - 2) + 1] = '\\';
    }
    s[x][y] = s[x +b[n] * 8 - 1][y] = s[x][y + b[n] * 8 - 1] = s[x + b[n] * 8 - 1][y + b[n] * 8 - 1] = '+';
    build(n - 1, x + b[n] * 4, y + b[n] * 2);
}

