#define MAX_N 512

char a[MAX_N][MAX_N];

void creat(int n, int bi, int bj, int si, int sj);
void print(int n);

int main(void){
    int i;
    int t, n;

    memset(a, ' ', sizeof(a));

    a[0][0] = a[MAX_N - 1][0] = a[0][MAX_N - 1] = a[MAX_N - 1][MAX_N - 1] = '+';

    for (i = 1; i < MAX_N - 1; i++){
        a[0][i] = a[MAX_N - 1][i] = '-';
        a[i][MAX_N - 1] = a[i][0] = '|';
    }
    creat(7, 0, 0, MAX_N - 1, MAX_N - 1);

    scanf("%d", &t);
    while (t--){
          scanf("%d", &n);
          print(n);
    }

    return 0;
}

void creat(int n, int bi, int bj, int si, int sj){
     int len = 1 << (n + 2);
     int nbi, nbj, nsi, nsj;
     int i, j;

     if (!n)
        return;

     for (j = 2; j < len / 2 - 1; j++){
         a[bi + len / 2 - j][bj + j] = '/';
         a[bi + len / 2 - j][bj + len - j - 1] = '\\';
     }

     nbi = bi + (len >> 1);
     nbj = bj + (len >> 2);
     nsi = si;
     nsj = sj - (len >> 2);

     a[nbi][nbj] = a[nbi][nsj] = a[nsi][nbj] = a[nsi][nsj] = '+';

     for (i = 1; i < len / 2 - 1; i++){
         a[nbi][nbj + i] = a[nsi][nbj + i] = '-';
         a[nbi + i][nbj] = a[nbi + i][nsj] = '|';
     }

     creat(--n, nbi, nbj, nsi, nsj);
}

void print(int n){
     int len = 1 << (n + 2);
     int bi = MAX_N - len;
     int bj = (MAX_N - len) >> 1;
     int i, j;

     for (i = 0; i < len; i++){
         for (j = 0; j < len; j++){
             putchar(a[bi + i][bj + j]); 
         }
         puts("");
     }
     puts("");
}

