#include <stdio.h>
#include <math.h>

void deal(int n,int i)
{
	int j,k;
	if(n==0)
	{
		if(i==1||i==4)
			printf("+--+");
		else
			printf("|  |");
		return ;
	}

	if(i==1)
	{
		for(j=1;j<=4*(int)pow(2,n);j++)
			if(j==1||j==4*(int)pow(2,n))
				printf("+");
			else
				printf("-");
	}
	else if(i<=2*(int)pow(2,n))
	{	
		for(j=1;j<=4*(int)pow(2,n);j++)
			if(j==1||j==4*(int)pow(2,n))
				printf("|");
			else if(i>=3&&i<=2*(int)pow(2,n)-1&&i+j==2+2*(int)pow(2,n))
				printf("/");
			else if(i>=3&&i<=2*(int)pow(2,n)-1&&j-i==2*(int)pow(2,n)-1)
				printf("\\");
			else
				printf(" ");
	}
	else if(i==4*pow(2,n))
	{
		for(j=1;j<=4*(int)pow(2,n);j++)
			if(j==1||j==4*(int)pow(2,n))
				printf("+");
			else if(j<=(int)pow(2,n)||j>=3*(int)pow(2,n))
				printf("-");
			else
			{
				deal(n-1,4*(int)pow(2,n-1));
				j+=2*(int)pow(2,n)-1;
			}
	}
	else
	{
		for(j=1;j<=4*(int)pow(2,n);j++)
			if(j==1||j==4*(int)pow(2,n))
				printf("|");
			else if(j<=(int)pow(2,n)||j>=3*(int)pow(2,n))
				printf(" ");
			else
			{
				deal(n-1,i-2*(int)pow(2,n));
				j+=2*(int)pow(2,n)-1;
			}
	}
}


int main()
{
	int T,n,i,j;
	scanf("%d",&T);
	for(i=0;i<T;i++)
	{
		scanf("%d",&n);
		for(j=1;j<=4*(int)pow(2,n);j++)
		{
			deal(n,j);
			printf("\n");
		}
	}
	return 0;
}

