int d[]={4,8,16,32,64,128,256,512,1024};

void deal(int n,int i)
{
	int j,k;
	if(n==0)
	{
		if(i==1||i==4)
			printf("+--+");
		else
			printf("|  |");
		return ;
	}
	if(i==1)
	{
		for(j=1;j<=d[n];j++)
			if(j==1||j==d[n])
				printf("+");
			else
				printf("-");
	}
	else if(i<=d[n-1])
	{	
		for(j=1;j<=d[n];j++)
			if(j==1||j==d[n])
				printf("|");
			else if(i>=3&&i<=d[n-1]-1&&i+j==2+d[n-1])
				printf("/");
			else if(i>=3&&i<=d[n-1]-1&&j-i==d[n-1]-1)
				printf("\\");
			else
				printf(" ");
	}
	else
	{
		for(j=1;j<=d[n];j++)
			if(j==1||j==d[n])
				if(i==d[n])
					printf("+");
				else
					printf("|");
			else if(j<=d[n]/4||j>=3*d[n]/4)
				if(i==d[n])
					printf("-");
				else
					printf(" ");
			else
			{
				deal(n-1,i-d[n-1]);
				j+=d[n-1]-1;
			}
	}
}


int main()
{
	int T,n,i,j;
	scanf("%d",&T);
	for(i=0;i<T;i++)
	{
		scanf("%d",&n);
		for(j=1;j<=d[n];j++)
		{
			deal(n,j);
			printf("\n");
		}
		printf("\n");
	}
	return 0;
}

