{
    if (n==0)
    {
        switch (l)
        {
            case 1:
            case 4:
                printf("+--+");
                break;
            default:
                printf("|  |");
        }
        return ;
    }
    if (l==1)
    {
        printf("+");
        for (int i=2;i<=w-1;i++)
            printf("-");
        printf("+");
        return ;
    }
    if ((l==2)||(l==w/2))
    {
        printf("|");
        for (int i=2;i<=w-1;i++)
            printf(" ");
        printf("|");
        return ;
    }
    if (l<w/2)
    {
        printf("|");
        for (int i=1;i<=w/2-l;i++)
            printf(" ");
        printf("/");
        for (int i=1;i<=2*l-4;i++)
            printf(" ");
        printf("\\");
        for (int i=1;i<=w/2-l;i++)
            printf(" ");
        printf("|");
        return ;
    }
    if (l==w)
    {
        printf("+");
        for (int i=1;i<=w/4-1;i++)
            printf("-");
        outit(n-1,l-w/2,w/2);
        for (int i=1;i<=w/4-1;i++)
            printf("-");
        printf("+");
        return ;
    }
    printf("|");
    for (int i=1;i<=w/4-1;i++)
        printf(" ");
    outit(n-1,l-w/2,w/2);
    for (int i=1;i<=w/4-1;i++)
        printf(" ");
    printf("|");
}
