procedure printhead(x,y,n:longint);
var i:longint;
begin
  map[x,y]:='+';
  for i:=1 to (1<<(n+2))-1 do map[x,y+i]:='-';
  map[x,y+i]:='+';
end;

procedure printmid(x,y,i,n:longint);
var j,k,l,r,llmt,rlmt:longint;
begin
  l:=(1<<(n+1))-(i-2);
  r:=(1<<(n+1))+(i-2);
  llmt:=1;
  rlmt:=1<<(n+2);
  map[x,y]:='|';
  map[x,y-1+1<<(n+2)]:='|';
  for j:=1 to (1<<(n+2)-2) do map[x,y+j]:=' ';
  if l=r then exit;
  if l=llmt+1 then exit;
  map[x,y-1+l]:='/';
  map[x,y+r]:='\';
end;

procedure printlast(x,y,i,n:longint);
var j,k:longint;
begin
  map[x,y]:='|';
  map[x,y-1+1<<(n+2)]:='|';
  for j:=1 to (1<<n-1) do begin
    map[x,y+j]:=' ';
    map[x,y-1+1<<(n+2)-j]:=' ';
  end;
end;

procedure build(x,y,n:longint);
var
  i,j:longint;
begin
  if n<0 then exit;
  printhead(x,y,n);
  for i:=2 to (1<<(n+1)) do printmid(x+i-1,y,i,n);
  build(x+i,y-1+(1<<n)+1,n-1);
  for i:=i+1 to (1<<(n+2)) do printlast(x+i-1,y,i,n);
end;

procedure print(n:longint);
var i,j:longint;
begin
  for i:=1 to (1<<(n+2))-1 do begin
    for j:=1 to (1<<(n+2)) do write(map[i,j]);
    writeln;
  end;
  for j:=1 to (1<<(n+2)) do if map[i,j]='|' then write('+') else write('-');
  writeln;
end;

