int p(int k){
	int m = 1;
	while (k > 1){
		m *= 2;
		k--;
	}
	return m;
}
int recordjiong(int k,int a,int b){
	int i,j,top = -1;
	do{
		for(i = 0;i < k * 8;i++){
			if(i == 0){
				for(j = 0;j < k * 8;j++){
					if(j == 0 || j == k*8-1)
						c[b+i][a+j] = '+';
					else
						c[b+i][a+j] = '-';
				}
			}
			else if(i == 1 || i == k * 4 -1){
				for(j = 0;j < k * 8;j++){
					if(j == 0 || j == k*8-1)
						c[b+i][a+j] = '|';
					else
						c[b+i][a+j] = ' ';
				}
			}
			else if(i > 1 && i < k * 4 - 1){
				for(j = 0;j < k * 8;j++){
					if(j == 0 || j == k*8-1)
						c[b+i][a+j] = '|';
					else if(j == 1 || j == k*8 -2){
						c[b+i][a+j] = ' ';
					}
					else if(j > 1 && j < k * 4){
						if(i + j == 4 * k )
							c[b+i][a+j] = '/';
						else
							c[b+i][a+j] = ' ';
					}
					else if(j >= k * 4 && j < k*8-2){
						if(j - i == 4 * k -1){
							c[b+i][a+j] = '\\';
						}
						else
							c[b+i][a+j] = ' ';
					}
				}
			}
			else if(i > k*4 - 1 && i < k*8 - 1){
				for(j = 0;j < k * 8;j++){
					if(j == 0 || j == k*8-1)
						c[b+i][a+j] = '|';
					else if(j > 0 && j < k * 2 || j >= k*6 && j < k*8 - 1 ){
						c[b+i][a+j] = ' ';
					}
				}
			}
			else if(i == k*8-1){
				for(j = 0;j < k * 8;j++){
					if(j == 0 || j == k*8-1)
						c[b+i][a+j] = '+';
					else if(j > 0 && j < k * 2 || j >= k*6 && j < k*8 - 1 ){
						c[b+i][a+j] = '-';
					}
				}
			}
		}
		if(k == 1){
			for(i = 0;i < 4;i++){
				if(i == 0 ){
					c[i+4+b][a+2] = '+';
					c[i+4+b][a+3] = '-';
					c[i+4+b][a+4] = '-';
					c[i+4+b][a+5] = '+';
				}
				else if( i == 3){
					c[i+4+b][a+2] = '+';
					c[i+4+b][a+3] = '-';
					c[i+4+b][a+4] = '-';
					c[i+4+b][a+5] = '+';
				}
				else if(i == 1 || i == 2){
					c[i+4+b][a+2] = '|';
					c[i+4+b][a+3] = ' ';
					c[i+4+b][a+4] = ' ';
					c[i+4+b][a+5] = '|';
				}
			}
			return 0;
		}
		a = 2*k+a;
		b = 4*k+b;
		k = k/2;
	}while(k > 0);
	return 0;
}

