			for (i=0;i<p;i++)
				if ((i==p-4*pow(2,k)))
				{
					for (j=p/2-pow(2,k+1);j<p/2+pow(2,k+1);j++)
						if (jiong[i][j]!='+') jiong[i][j]='-';
				}else if (i==p-1)
					for (j=0;j<p;j++) 
						if (jiong[i][j]!='+') jiong[i][j]='-';
		for (k=1;k<=n+1;k++)
			for (j=0;j<p;j++)
				if ((j==p/2-pow(2,k))||(j==p/2-1+pow(2,k)))
					for (i=p-4*pow(2,k-1);i<p;i++)
						if (jiong[i][j]!='+') jiong[i][j] = '|';

		for (k=1;k<=n;k++)
			for (i=int(p-4*pow(2,k))+2;i<p-4*pow(2,k-1)-1;i++)
				{
					jiong[i][int(p/2-(i-p+4*pow(2,k)-2)-2)] = '/';
