  ch[x][y]='+';
  for (i=1;i<cd[p]-1;i++)
    {
      ch[x+i][y]='|';
      ch[x][y+i]='-';
      ch[x+i][y+cd[p]-1]='|';
      ch[x+cd[p]-1][y+i]='-';                   
    }
  ch[x+cd[p]-1][y]='+';
  ch[x][y+cd[p]-1]='+';
  ch[x+cd[p]-1][y+cd[p]-1]='+';
  x++;y+=pow(2,p+1)-1;
