int weizhi(int m,int n,int l)
{
	int a,b,e=0,x1,x2,x11,x22,y,i;
	a=1;b=2;
	x11=x22=l/2;
	for(i=0;a<l/2;i++){
		a=a*2;
		b=b*2;
		x11=x1;
		x22=x2;
		x1=l/2-a;
		x2=l/2+a-1;
		y=l-b;
		if((y<=m<y+b/2 && x1<=n<=x2) || (y+b/2<=m<l-1 && x1<=n<x11) ||(y+b/2<=m<l-1 && x22<n<=x2)){
		if(m==y){
			if((n==x1) ||(n==x2)) e=1;
			else if(x1<n<x2) e=2;

		}
		else if(y<m<l-1){
			if(n==x1 || n==x2) e=3;
		}

		if(b>4){
			if(((y+b/2)-m)>1 && (n-x1)>1 && ((y+b/2)-m)==(n-x1) && (n-x1)<(l/2-1)) e=4;
			if(((y+b/2)-m)>1 && (x2-n)>1 && ((y+b/2)-m)==(x2-n) && (x2-n)>l/2) e=5;

		}
	}
	}
	return e;

}

