int pow(int n,int m)
{
	int i,s=1;
	for(i=0;i<m;i++)
		s*=n;
	return s;
}
void digui(char **a,int n,int qix,int qiy)
{
	int i,j;
	int meimao1,meimao2,qix1,qiy1,changdu;
	changdu=pow(2,n+2);
	meimao1=-1+(changdu/2)+qix;
	meimao2=1+(changdu/2)+qix;
	if(n<0) return ;
	for(i=0;i<changdu;i++)
	{
		for(j=0;j<changdu;j++)
		{
			if(i==0||i==changdu-1)
				a[qix+i][qiy+j]='-';
			if(j==0||j==changdu-1)
				a[qix+i][qiy+j]='|';
			if((j==0&&i==0)||(i==0&&j==changdu-1)||(i==changdu-1&&j==0)&&(i==changdu-1&&j==changdu-1))
				a[qix+i][qiy+j]='+';
		}
		if(i<pow(2,n+1)-1&&i>1&&meimao1>qix+1)
			{
				a[qix+i][meimao1-1-qix/2]='/';
				meimao1--;
			}
		if(i<pow(2,n+1)-1&&i>1&&meimao2<qix+changdu-1)
		{
			a[qix+i][meimao2-qix/2]='\\';
			meimao2++;
		}
	}
	a[qix+changdu-1][qiy+changdu-1]=a[qix+changdu-1][qiy]='+';
	qix1=qix+pow(2,n+1);
	qiy1=qiy+pow(2,n);
	digui(a,n-1,qix1,qiy1);
}
