     for (int i = 1; i <= L; i++) ch[x][y+i-1] = '-';
     for (int i = 1; i <= L; i++) ch[x+1][y + i - 1] = ' ';
     int W = (L - 6) / 2, mid;
     //cout << L << " " << W << endl;
     for (int i = 1; i <= W; i++) {
         ch[x+i+1][y] = ch[x+i+1][y + L - 1] = '|';
