     for (int i = 1; i <= L; i++) ch[x+i-1][y] = ch[x+i-1][y+L-1] = '|';

     for (int i = 1; i <= L; i++) ch[x+L-1][y+i-1] = '-';
     ch[x][y] = ch[x][y + L - 1] = '+';
     ch[x+L-1][y] = ch[x+L-1][y + L- 1] = '+';

