#include <cstdio>
#include <cstdlib>
#include <algorithm>
using namespace std;

int EyeLen[8];
int FaceLen[8];

void PrintUpperLine(int len, char EndPointChar, char LineChar) {
    putchar(EndPointChar);
    for (int i = 0; i < len; ++i)
        putchar(LineChar);
    putchar(EndPointChar);
}
void PrintEyeAt(int n, int serial) {
    putchar('|');
    for (int i = serial; i < EyeLen[n]; ++i)
        putchar(' ');
    putchar('/');
    for (int i = 0; i <= serial; ++i)
        printf("  ");
    putchar('\\');
    for (int i = serial; i < EyeLen[n]; ++i)
        putchar(' ');
    putchar('|');
}

void PrintJIONGAtLine(int n, int elen, int line) {
    if (line == 0)
        PrintUpperLine(elen, '+', '-');
    else if (line == 1 || line == 2 + EyeLen[n])
        PrintUpperLine(elen, '|', ' ');
    else if (line < 2 + EyeLen[n])
        PrintEyeAt(n, line - 2);
    else if (line <= elen) {
        putchar('|');
        for (int i = 0; i < FaceLen[n]; ++i)
            putchar(' ');
        if (n > 0)
            PrintJIONGAtLine(n - 1, (elen - 2) / 2, line - EyeLen[n] - 3);
        for (int i = 0; i < FaceLen[n]; ++i)
            putchar(' ');
        putchar('|');
    }
    else {
        putchar('+');
        for (int i = 0; i < FaceLen[n]; ++i)
            putchar('-');
        if (n > 0)
            PrintJIONGAtLine(n - 1, (elen - 2) / 2, line - EyeLen[n] - 3);
        for (int i = 0; i < FaceLen[n]; ++i)
            putchar('-');
        putchar('+');
    }
}

int main() {
    EyeLen[1] = 1;
    FaceLen[0] = FaceLen[1] = 1;
    for (int i = 2; i <= 7; ++i) {
