void ready()
{
    int i, j;
    s[0][1][1] = '+';
    s[0][1][4] = '+';
    s[0][4][1] = '+';
    s[0][4][4] = '+';
    for(i = 2; i <= 3; i++)
    {
        s[0][1][i] = '-';
        s[0][4][i] = '-';
    }
    for(i = 2; i <= 3; i++)
    {
        s[0][i][1] = '|';
        s[0][i][4] = '|';
    }
    for(i = 2; i <= 3; i++)
    {
        for(j = 2; j <= 3; j++)
        s[0][i][j] = ' ';
    }
}
void make()
{
    int i, j, k;
    for(k = 1; k <= 7; k++)
    {
        int top = (1 << (k + 2));
        s[k][1][1] = '+';
        s[k][1][top] = '+';
        s[k][top][1] = '+';
        s[k][top][top] = '+';
        for(i = 2; i <= top - 1; i++)
        s[k][1][i] = '-';
        for(i = 2; i <= top - 1; i++)
        {
            s[k][i][1] = '|';
            s[k][i][top] = '|';
        }
        for(i = 2; i <= top - 1; i++)
        s[k][2][i] = ' ';
        int ot = top / 2 - 3;
        for(i = 1; i <= ot; i++)
        {
            int ct = (top - 2 - i * 2 - 2) / 2;
            for(j = 2; j < ct + 2; j++)
            {
                s[k][i + 2][j] = ' ';
            }
            s[k][i + 2][ct + 2] = '/';
            for(j = ct + 3; j < ct + 3 + i * 2; j++)
            {
                s[k][i + 2][j] = ' ';
            }
            s[k][i + 2][ct + 3 + i * 2] = '\\';
            for(j = ct + 3 + i * 2 + 1; j < top; j++)
            s[k][i + 2][j] = ' ';
        }
            for(j = 2; j < top; j++)
            s[k][top / 2][j] = ' ';

        int pt = (top / 2 - 2) / 2;
        for(i = top / 2 + 1; i <= top; i++)
        {
            for(j = 2; j < pt + 2; j++)
            s[k][i][j] = ' ';
            for(j = pt + 2; j < pt + 2 + top / 2; j++)
            s[k][i][j] = s[k - 1][i - top / 2][j - pt - 1];
            for(j = pt + 2 + top / 2; j < top; j++)
            s[k][i][j] = ' ';
        }
        for(i = 2; i < pt + 2; i++)
        s[k][top][i] = '-';
        for(i = top - 1; i >= top - pt; i--)
        s[k][top][i] = '-';
    }
}
int main()
{
    int T, n, i, j;
    ready();
    make();
    scanf("%d", &T);
