using namespace std;

int dis[8],pow[8];
void Print(int n,int l)
{
    int i,cur;

    if (l==1)
    {
        printf("+");
        for (i=0;i<dis[n];i++)
            printf("-");
        printf("+");
    }
    else if (l==2)
    {
        printf("|");
        for (i=0;i<dis[n];i++)
            printf(" ");
        printf("|");
    }
    else if (l<pow[n])
    {
        printf("|");
        for (i=0;i<dis[n]/2-1-(l-2);i++)
            printf(" ");
        printf("/");
        for (i=0;i<(l-2)*2;i++)
            printf(" ");
        printf("\\");
        for (i=0;i<dis[n]/2-1-(l-2);i++)
            printf(" ");
        printf("|");
    }
    else if (l==pow[n])
    {
        printf("|");
        for (i=0;i<dis[n];i++)
            printf(" ");
        printf("|");
    }
    else
    {
        cur=l-pow[n];

        if (l==pow[n]*2)
            printf("+");
        else
            printf("|");

        for (i=0;i<dis[n-1]/2;i++)
            if (l==pow[n]*2)
                printf("-");
            else
                printf(" ");

        if (n>1)
            Print(n-1,cur);
        else
        {
            if (cur==1)
                printf("+--+");
            else if (cur==2)
                printf("|  |");
            else if (cur==3)
                printf("|  |");
            else
                printf("+--+");
        }

        for (i=0;i<dis[n-1]/2;i++)
            if (l==pow[n]*2)
                printf("-");
            else
                printf(" ");
        if (l==pow[n]*2)
            printf("+");
        else
            printf("|");
    }
}

int main()
{
    int t,i,n;

    pow[0]=2;
    for (i=1;i<=7;i++)
        pow[i]=pow[i-1]*2;

    dis[0]=2;
    for (i=1;i<=7;i++)
        dis[i]=dis[i-1]+pow[i];

    scanf("%d",&t);
    while (t--)
    {
        scanf("%d",&n);

        for (i=1;i<=pow[n]*2;i++)
        {
            Print(n,i);
            printf("\n");
        }
        printf("\n");
    }

    return 0;
}

