#define MAXL 1100

using namespace std;

char ans[MAXL][MAXL];

int build(int x,int y,int n){
    //printf("%d %d %d\n",x,y,n);
    if (n==2) return 2;
    //int l = 8 * (1 << (n - 1));
    int l = n;
    int i,j;
    ans[x][y] = '+';
    ans[x+l-1][y] = '+';
    ans[x][y+l-1] = '+';
    ans[x+l-1][y+l-1] = '+';
    for (i=y+1;i<y+l-1;i++) ans[x][i] = ans[x+l-1][i] = '-';
    for (i=x+1;i<x+l-1;i++) ans[i][y] = ans[i][y+l-1] = '|';
    //int m = (1 << (n+1)) - 3;
    int m = l / 2 - 3;
    int si = x + l / 2 - 2;
    int sj = y + 2;
    for (i=0;i<m;i++) ans[si-i][sj+i] = '/';
    si = x + l / 2 - 2;
    sj = y + l - 3;
    for (i=0;i<m;i++) ans[si-i][sj-i] = '\\';
    build(x+l/2,y+l/4,n/2);
    return l;
}

