    for ( int i = 1 ; i <= n ; i++ )
        s  = (s+1)*2 +1;
    return s;
}
int abc( int a, int b)
{
    int s = 1;
    for ( int i = 1 ; i <= b ; i++ )
        s *= a;
    return s;
}
void print( int n, int h )
{
    int hs;
    int s;
    int i;
    hs = 4*(int)pow(2,n);
