            printf("|  |");
        return ;
    }
    if ( h == 1 )
    {
        s = 4*abc(2,n);
        printf("+");
        for ( int i = 1 ; i <= s-2 ; i++ )
            printf("-");
        printf("+");
    }
    if ( h == 2 )
    {
        s = 4*(int)abc(2,n);
        printf("|");
        for ( int i = 1 ; i <= s-2 ; i++ )
            printf(" ");
        printf("|");
    }
    int sb = qiuhe(n);
    if ( h > 2 && h <= sb + 2 )
    {
        printf("|");
