            printf(" ");
        printf("/");
        for ( i = 2 ; i < h ; i++ )
            printf("  ");
        printf("\\");
        for ( i = h ; i <= sb+2 ; i++ )
            printf(" ");
        printf("|");
    }
    if ( h == sb+3 )
    {
        s = 4*abc(2,n);
        printf("|");
        for ( int i = 1 ; i <= s-2 ; i++ )
            printf(" ");
        printf("|");
    }
    if ( h > sb+3 && h < hs )
