void tree(char** output_buffer, size_t x, size_t y, bool direction, size_t distance_remaining, size_t cur_age){
    if(y == 0){
        output_buffer[y][x] == 'O';
        return;
    }
    if(cur_age <= 0){
        return;
    }

    //Check if we need to branch
    if(distance_remaining == 0){
        output_buffer[y][x] = 'Y';
        size_t new_distance = (1 << (cur_age - 1)) - 1; //2^(cur_age-1) - 1
        if(cur_age == 0){
            new_distance = 0;
        }
        //Make a fork to the left
        tree(output_buffer, x - 1, y - 1, true, new_distance, cur_age - 1);
        //Make a fork to the right
        tree(output_buffer, x + 1, y - 1, false, new_distance, cur_age - 1);
        return;
    }

    //If 'true' then go left. If 'false' then go right
    output_buffer[y][x] = direction ? '\\' : '/';
    if(direction){
        tree(output_buffer, x - 1, y - 1, direction, distance_remaining - 1, cur_age);
    }else{
        tree(output_buffer, x + 1, y - 1, direction, distance_remaining - 1, cur_age);
    }
}

