		return Math.log(n) / Math.log(base);
	}
	
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int totalTrees = scan.nextInt();
		ArrayList<Integer> treeAges = new ArrayList<>();
		
