import java.util.Scanner;

public class Fractal {

	private static int[] fractalLevels;

	public static void main(String[] args) {
		char[][][] fractalPatterns = getUserFractalPatterns();

		if (fractalPatterns == null) 
			return;
		else printFractals(fractalPatterns);	
	}

	public static char[][][] getUserFractalPatterns() {

		Scanner input = new Scanner(System.in);
		int fractalNumber;
		char fractalPatterns[][][];

		try {

			// Getting and validating the number of fractals to print from the user
			fractalNumber = Integer.parseInt(input.nextLine());
			if (fractalNumber < 0)
				throw new Exception("ERROR: Number of fractals must be positive");

			fractalLevels = new int[fractalNumber];
			fractalPatterns = new char[fractalNumber][3][3];

			// Getting the level to print each fractal at and the fractal
			// patterns (at level 2) for the number of fractals specified above.
			for (int fractalIndex = 0; fractalIndex < fractalPatterns.length; fractalIndex++) {

				// Getting the desired fractal level to print out the current fractal at
				fractalLevels[fractalIndex] = Integer.parseInt(input.nextLine());
				if (fractalLevels[fractalIndex] < 1 || fractalLevels[fractalIndex] > 7)
					throw new Exception("ERROR: Specified fractal level must be less than or equal to 7");

				// Getting fractal pattern for the current fractal
				String[] fractalPattern = new String[3];
				fractalPattern[0] = input.nextLine();
				fractalPattern[1] = input.nextLine();
				fractalPattern[2] = input.nextLine();

				if (fractalPattern[0].length() != 3 || fractalPattern[1].length() != 3 || fractalPattern[2].length() != 3) 
					throw new Exception("ERROR: Invalid fractal pattern, must be 3x3 in size");

				for (int i = 0; i < fractalPattern.length; i++) {

					// Verifying chars are valid characters (spaces or lowercase o's)
					char[] rowContents = fractalPattern[i].toCharArray();
					if (!(rowContents[0] == ' ' || rowContents[0] == 'o') ||
							!(rowContents[1] != ' ' || rowContents[1] != 'o') ||
							!(rowContents[2] != ' ' || rowContents[2] != 'o')) {
						throw new Exception("ERROR: Invalid fractal pattern, must contain spaces or lowercase o's"); 
					}

					fractalPatterns[fractalIndex][i] = rowContents;
				}
			}

		} catch (Exception e) {
			System.out.println(e.getMessage());
			input.close();
			return null;
		}

		input.close();
		return fractalPatterns;
	}

	public static void printFractals(char[][][] fractalPatterns) {

		for (int fractalIndex = 0; fractalIndex < fractalPatterns.length; fractalIndex++) {

			int sideLength = (int) Math.pow(3, fractalLevels[fractalIndex] - 1);

			// Level 1 fractals are just a single 'o'
			if (sideLength <= 1) {				
				System.out.println("o");
			} else {

				char[][] currentFractal = fractalPatterns[fractalIndex];
				char[][] outputArray = new char[sideLength][sideLength];
				fractalRecursiveGenerator(currentFractal, outputArray);

				for (int y = 0; y < outputArray.length; y++) {
					for (int x = 0; x < outputArray[0].length; x++) {
						System.out.print(outputArray[y][x]);
					}
					System.out.println();
				}
			}			
		}
	}

	public static void fractalRecursiveGenerator(char[][] fractalPattern, char[][] returnArray) {

		// Base case for the lowest level of recursion
		if (returnArray.length == 3) {
			for (int y = 0; y < fractalPattern.length; y++) {
				for (int x = 0; x < fractalPattern[0].length; x++) {
					returnArray[y][x] = fractalPattern[y][x];
				}
			}
		}

		// There exists further recursive levels, fractal continues generation
		else {

			// Double for-loops for each part of the 3x3 fractal pattern
			for (int fractalY = 0; fractalY < fractalPattern.length; fractalY++) {
				for (int fractalX = 0; fractalX < fractalPattern[0].length; fractalX++) {

					char[][] newReturnArray = new char[returnArray.length / 3][returnArray.length / 3];

					// Recursive call since the fractal continues
					if (fractalPattern[fractalY][fractalX] == 'o') {
						fractalRecursiveGenerator(fractalPattern, newReturnArray);
					}

					// Fractal doesn't continue at the next section, fill all values for the new return arrays as spaces
					else {
						for (int newReturnY = 0; newReturnY < newReturnArray.length; newReturnY++) {
							for (int newReturnX = 0; newReturnX < newReturnArray[0].length; newReturnX++) {
								newReturnArray[newReturnY][newReturnX] = ' ';
							}
						}
					}

					// Putting values in the return array
					for (int newReturnY = 0; newReturnY < newReturnArray.length; newReturnY++) {
						for (int newReturnX = 0; newReturnX < newReturnArray[0].length; newReturnX++) {
							returnArray[fractalY * newReturnArray.length + newReturnY]
									   [fractalX * newReturnArray.length + newReturnX] = newReturnArray[newReturnY][newReturnX];
						}
					}
				}
			}
		}
	}
}

