            System.out.println("Fractal for Shape #" + (i + 1) + ":");
            printGrid(finalFractal);
            System.out.println(); // Extra space for clarity between fractals
        }
    }

    private static int getNShapes(Scanner scanner) {
        int nShapes = -1;

        try {
            System.out.println("Enter the number of shapes to be created: ");
            nShapes = Integer.parseInt(scanner.nextLine());
        } catch (NumberFormatException e) {
            System.out.println("Invalid input for line 1. Please enter a number.");
        }
        return nShapes;
    }

    // simple function to get integer nLevels
    private static int getLevelInput(Scanner scanner) {
        int level = -1;

        try {
            System.out.println("Enter the level of fractal to be created: ");
            level = Integer.parseInt(scanner.nextLine());
        } catch (NumberFormatException e) {
            System.out.println("Invalid input for line 1. Please enter a number 1 - 7.");
        }

        if (level < 0 || level > 7) {
            System.out.println("Invalid input for line 1. Please enter a number between 1 and 7.");
            getLevelInput(scanner);
        }
        return level;
    }

    /*
     * Method to get input from the user
     * Inputs include multiple groups of samples
     * The first line is the groups of fractals m
     * The second line and all lines after are sample fractals
     * Each sample fractal is described in four lines
     */
    private static char[][] getGridInput(Scanner scanner) {
        // local grid to be returned
        char[][] userGrid = new char[3][3];

        System.out.println("Enter the 3x3 grid for the fractal on 3 separate lines: ");
        // only grab 3 lines from user input
        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine(); // Read the whole line
            for (int j = 0; j < 3; j++) {
                userGrid[i][j] = line.charAt(j);
            }
        }

        // return the user input
        return userGrid;
    }

    //print multi dimensional char array
    private static void printGrid(char[][] grid) {
        int size = grid.length; // The size of the full fractal grid

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
        System.out.println(); // Blank line after the fractal
    }

    private static char[][] generateFractal(char[][] userGrid, int levels) {

        // base case
        if (levels == 2) {
            return userGrid;
        }

        // Generate fractal of previous level (n-1)
        char[][] smallerFractal = generateFractal(userGrid, levels - 1);
        int oldSize = smallerFractal.length;
        int newSize = oldSize * 3;

        // Create the new empty grid
        char[][] fractalGrid = new char[newSize][newSize];

        // Fill the grid with spaces initially
        for (int i = 0; i < newSize; i++) {
            for (int j = 0; j < newSize; j++) {
                fractalGrid[i][j] = ' ';
            }
        }

        // Copy smaller fractal into the correct five positions
        for (int i = 0; i < oldSize; i++) {
            for (int j = 0; j < oldSize; j++) {
                char ch = smallerFractal[i][j];

                // Place copies in the five required positions
                fractalGrid[i][j] = ch;             // Top-left
                fractalGrid[i][j + 2 * oldSize] = ch; // Top-right
                fractalGrid[i + oldSize][j + oldSize] = ch; // Center
                fractalGrid[i + 2 * oldSize][j] = ch; // Bottom-left
                fractalGrid[i + 2 * oldSize][j + 2 * oldSize] = ch; // Bottom-right
            }
        }
        return fractalGrid;
    }

    /*
     * For each set of characters specifying a fractal, print out corresponding fractal at n level
     * print a blank line after each fractal
     * Do not keep an extra empty space in any line
     * X(n-1) X(n-1)
     *     X(n-1)
     * X(n-1) X(n-1)
     */
    private static char[][] generateFractalBackup(char[][] userGrid, int levels) {
        if (levels == 1) {
            return new char[][]{{userGrid[1][1]}}; // Return just the center character
        } else if (levels == 2) {
            return userGrid; // Base level 2 should be the user input
        }

        int gridSize = (int) Math.pow(3, levels - 1);
        char[][] fractalGrid = new char[gridSize][gridSize];

        // Fill the entire grid with repeated copies of userGrid
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                fractalGrid[i][j] = userGrid[i % 3][j % 3];
            }
        }

        return fractalGrid;
    }

    //print multi dimensional char array to print 3x3 grid
    private static void printGridBackup(char[][] grid, char[][] userGrid) {
        int size = grid.length; // The size of the full fractal grid

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < 3; j++) { // Loop through userGrid’s 3 columns
                if (userGrid[i % 3][j] != ' ') {
                    // Print the next 3 characters from the fractal grid
                    for (int k = 0; k < 3; k++) {
                        System.out.print(grid[i][j * 3 + k]);
                    }
                } else {
                    // Otherwise, print 3 spaces
                    System.out.print("   ");
                }
            }
            System.out.println();
        }
        System.out.println(); // Blank line after the fractal
    }
}

