import java.util.Scanner;

public class Fractal {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        System.out.println("Input the number of fractals");
        int x = scan.nextInt();
        scan.nextLine();

        for (int i = 0; i < x; i++) {
            System.out.println("Input your fractal level");
            int level = scan.nextInt();
            scan.nextLine();

            String[] charArray = new String[3];
            for (int j = 0; j < 3; j++) {
                charArray[j] = scan.nextLine();
            }

            String[] result = leveler(charArray, level);
            for (String row : result) {
                System.out.println(row);
            }
            System.out.println();
        }
        scan.close();
    }

    static String[] leveler(String[] input, int level) {
        if (level == 2) {
            return input;
        }
        String[] original = leveler(input, level - 1);
        int size = original.length;
        int newSize = size * 3;
        String[] grid = new String[newSize];
        for (int i = 0; i < newSize; i++) {
            grid[i] = " ".repeat(newSize);
        }
        for (int i = 0; i < size; i++) {
            grid[i] = original[i] + " ".repeat(size) + original[i];
        }
        for (int i = 0; i < size; i++) {
            int midPadding = size / 2;
            grid[size + i] = " ".repeat(midPadding) + original[i] + " ".repeat(midPadding);
        }
        for (int i = 0; i < size; i++) {
            grid[2 * size + i] = original[i] + " ".repeat(size) + original[i];
        }

        return grid;
    }
}

