import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class Fractal {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        scanner.nextLine();

        List<String[]> allFractals = new ArrayList<>();

        for (int group = 0; group < m; group++) {
            int n = scanner.nextInt();
            scanner.nextLine();
            String[] patternRows = new String[3];
            for (int i = 0; i < 3; i++) {
                patternRows[i] = scanner.nextLine();
            }
            String[] result = generateFractal(patternRows, n);
            allFractals.add(result);
        }

        scanner.close();

        for (int i = 0; i < allFractals.size(); i++) {
            printFractal(allFractals.get(i));
            if (i < allFractals.size() - 1) {
                System.out.println();
            }
        }
    }

    public static String[] generateFractal(String[] level2Pattern, int n) {
        if (n == 2) {
            return level2Pattern;
        }

        String[] previousLevel = generateFractal(level2Pattern, n - 1);
        int numRows = previousLevel.length * 3;
        String[] result = new String[numRows];

        for (int i = 0; i < numRows; i++) {
            result[i] = "";
        }
        for (int prevRow = 0; prevRow < previousLevel.length; prevRow++) {
            String currentRow = previousLevel[prevRow];

            for (int charIndex = 0; charIndex < currentRow.length(); charIndex++) {
                char currentChar = currentRow.charAt(charIndex);

                for (int l2Row = 0; l2Row < level2Pattern.length; l2Row++) {
                    if (currentChar != ' ') {
                        while (result[prevRow * 3 + l2Row].length() < charIndex * level2Pattern[0].length()) {
                            result[prevRow * 3 + l2Row] += " ";
                        }
                        result[prevRow * 3 + l2Row] += level2Pattern[l2Row];
                    } else {
                        for (int i = 0; i < level2Pattern[l2Row].length(); i++) {
                            result[prevRow * 3 + l2Row] += " ";
                        }
                    }
                }
            }
        }

        return result;
    }

    public static void printFractal(String[] fractal) {
        for (String line : fractal) {
            String trimmed = line.replaceAll("\\s+$", "");
            System.out.println(trimmed);
        }
    }
}

