                baseFractal[row] = (line + "   ").substring(0, 3).toCharArray();  // Ensures exactly 3 characters
            }

            // fractal for level n
            char[][] fractal = genFrac(n, baseFractal);
            printFractal(fractal);
            // necessary whitespace
            if (i < m - 1) {
                System.out.println();
            }
        }
        scanner.close();
