    // recursively gen fractal
    private static char[][] genFrac(int n, char[][] baseFractal) {
        if (n == 2) {
            return baseFractal;
        }

        char[][] priorFrac = genFrac(n - 1, baseFractal);
        int size = priorFrac.length;
        int newSize = 2 * size + 1;
        char[][] fractal = new char[newSize][newSize];

        // Fill the new fractal with spaces
        for (char[] row : fractal) {
            Arrays.fill(row, ' ');
        }

        // Calc center offset
