        // Copy smaller fractals into correct positions
        copyFractal(fractal, priorFrac, 0, 0); //TL
        copyFractal(fractal, priorFrac, 0, size + 1); //TR
        copyFractal(fractal, priorFrac, size + 1, 0); //BL
        copyFractal(fractal, priorFrac, size + 1, size + 1); //BR
        copyFractal(fractal, priorFrac, cOff, cOff); // Center

        return fractal;
    }

    // Copy smaller fractal into larger fractal at a specific position
    private static void copyFractal(char[][] dest, char[][] src, int rowOffset, int colOffset) {
        int size = src.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                dest[rowOffset + i][colOffset + j] = src[i][j];
            }
        }
    }

    private static void printFractal(char[][] fractal) {
        for (char[] row : fractal) {
            System.out.println(new String(row).stripTrailing());
        }
    }
}

