import java.util.*;
public class Fractal {
    public static void main(String[] args) {
        int numPrintedFracs = 0;
        Scanner scanner = new Scanner(System.in);
        // read first line: groups of fractals m
        int m = Integer.parseInt(scanner.nextLine());
        // deal w/ each fractal group
        for (int i = 0; i < m; i++) {
            int n = Integer.parseInt(scanner.nextLine()); // level of frac to be printed

            // read original level 2 fractal, and store in matrix
            char[][] OGFrac = new char[3][3];
            for (int row = 0; row < 3; row++) {
                OGFrac[row] = scanner.nextLine().toCharArray();
            }

            // gen level n frac, print, update counter
            char[][] frac = generateFractal(n, OGFrac);
            printFractal(frac);
            numPrintedFracs++;

            // deal w/ whitespace between fracs
            if (numPrintedFracs < m) {
                System.out.println();
            }
        }
        scanner.close();
    }

    private static char[][] generateFractal(int n, char[][] OGFrac) {
        if (n == 2) { // base case
            return OGFrac;
        }
        // gen last level frac
        char[][] prevFrac = generateFractal(n - 1, OGFrac);
        // last side length used for size calc
        int sL = prevFrac.length;
        int size = sL*3;
        // initialize empty frac then fill with whitespace
        char[][] frac = new char[size][size];
        for (char[] row : frac) {
            Arrays.fill(row, ' ');
        }

        // iterate through the 3x3 2D matrix to find correct subfractal placement
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                // Bring in OGFrac relative to its contents
                if (OGFrac[row][col] != ' ') {
                    int startX = sL*row; // prevFrac pos calcs
                    int startY = sL*col;

                    copyFractal(frac, prevFrac, startX, startY);
                }
            }
        }
        return frac;
    }
    // copy smaller frac into larger at correct row/coll offsets
    private static void copyFractal(char[][] big, char[][] small, int rOfs, int cOfs) {
        int size = small.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                big[rOfs + i][cOfs + j] = small[i][j];
            }
        }
    }

    private static void printFractal(char[][] frac) {
        for (char[] row : frac) {
            System.out.println(new String(row).stripTrailing());
        }
    }
}

