import java.util.Scanner;
import java.lang.Math;

public class Fractal {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        System.out.println("enter number of fractals:");
        int fractalNum = scan.nextInt(); 

        int[] nLevels = new int[fractalNum];

        String[][] fractals = new String[fractalNum][3];
        for (int i = 0; i < fractalNum; i++) {
            System.out.println("enter n level:");
            nLevels[i] = scan.nextInt();
            scan.nextLine();

            if (nLevels[i] != 1) {
                System.out.println("enter three lines for fractal: ");
                fractals[i][0] = scan.nextLine();
                fractals[i][1] = scan.nextLine();
                fractals[i][2] = scan.nextLine();
            }

            // newline
            System.out.println();
        }

        // one loop for each fractal
        for (int i = 0; i < fractalNum; i++) {
            System.out.println("\n\n");

            int level = nLevels[i];
            if (level == 1) {
                System.out.println("0");
                continue;
            } 

            String[] n2Fractal = {fractals[i][0], fractals[i][1], fractals[i][2]};

            if (level == 2) {
                System.out.println(n2Fractal[0] + "\n" + n2Fractal[1] + "\n" + n2Fractal[2]);
                continue;
            }

            // exponential code for 3 <= n <= 7
            String[] currentNFractal;
            for (int j = 3; j <= level; j++) {
                int newLength = (int)Math.pow(3, (double) j-1);
                currentNFractal = new String[newLength];

                int distanceFromEdge = 0;

                // create corners and work its way into the center
                // loop is over when the center is the last thing left
                while (distanceFromEdge < newLength / 2) {
                    // creating n2 fractal for all four corners
                    for (int n2Line = 0; n2Line < 3; n2Line++) {
                        // top left
                        currentNFractal[distanceFromEdge] = addSpaces(currentNFractal[distanceFromEdge], distanceFromEdge);

                        currentNFractal[distanceFromEdge] += n2Fractal[n2Line];

                        // bottom left
                        currentNFractal[newLength - 1 - n2Line] = addSpaces(currentNFractal[newLength - 1 - n2Line], distanceFromEdge);

                        currentNFractal[newLength - 1 - distanceFromEdge] += n2Fractal[n2Line];

                        // middle spaces, needs fixing
                        for (int spaces = 0; spaces < newLength - 6; spaces++) {
                            currentNFractal[distanceFromEdge] += " ";
                            currentNFractal[newLength - 1 - n2Line] += " ";
                        }


                        // top right
                        currentNFractal[distanceFromEdge] += addSpaces(currentNFractal[distanceFromEdge], distanceFromEdge);

                        currentNFractal[distanceFromEdge] += n2Fractal[n2Line];

                        // bottom right
                        currentNFractal[newLength - 1 - n2Line] += addSpaces(currentNFractal[newLength - 1 - n2Line], distanceFromEdge);

                        currentNFractal[newLength - 1 - distanceFromEdge] += n2Fractal[n2Line];
                    }

                    // adjust bounds for moving one fractal closer to the center
                    // this iterates by 3 with every fractal made
                    distanceFromEdge += 3;
                }

                // create fractal at center
                // not implemented

                for (int finalFractalLines = 0; finalFractalLines < newLength; finalFractalLines++) {
                    System.out.println(currentNFractal[finalFractalLines]);
                }



            }
        }
        scan.close();
    }

    public static String addSpaces(String fractalLine, int distance) {
        // edge case for first iteration
        if (distance == 0) {
            return "";
        }

        for (int borderSpaces = 0; borderSpaces < distance; borderSpaces++) {
            fractalLine  += " ";
        }
        return fractalLine;
    }
}

