                fractals[i][1] = scan.nextLine();
                fractals[i][2] = scan.nextLine();
            }

            // newline
            System.out.println();
        }

        // one loop for each fractal
        for (int i = 0; i < fractalNum; i++) {
            System.out.println("\n\n");

            int level = nLevels[i];
            if (level == 1) {
                System.out.println("0");
                continue;
            } 

            if (level == 2) {
                System.out.println(fractals[i][0] + "\n" + fractals[i][1] + "\n" + fractals[i][2]);
                continue;
            }

            char[][] n2Fractal = {fractals[i][0].toCharArray(), fractals[i][1].toCharArray(), fractals[i][2].toCharArray()};

            char[][] fullFractal = recursiveFractalCall(level, n2Fractal);


            // print out fractal
            for (char[] row : fullFractal) {
                System.out.println(new String(row));
            }

            }

        scan.close();
    }

    // calls the recursive function
    public static char[][] recursiveFractalCall(int level, char[][] n2Fractal) {
        return fillOutFractal(3, level, n2Fractal, n2Fractal);
    }

    public static char[][] fillOutFractal(int currentLevel, int level, char[][] n2Fractal, char[][] fractal) {
        // works with level 2 first, inside out

        int fractalLength = (int) Math.pow(3, (double) (currentLevel - 1));
        char[][] currentFractal = new char[fractalLength][fractalLength];
        for (int i = 0; i < fractalLength; i++) {
            Arrays.fill(currentFractal[i], ' ');  // Initialize with spaces
        }

        // shifts where the fractal is filled in
        // to make sure the index starts at the top-left
        // of each section.
        int startingColumnIndex = 0;
        int startingRowIndex = 0;

        // iterates through all nine secions of each fractal
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {

                // second part of the conditional is an edge case,
                // to make sure the center is filled out even if the center of n2Fractal is empty
                if (n2Fractal[i][j] != ' ' || (i == 1 && j == 1)) {
                    // fill in section with fractal
                    for (int column = 0; column < fractal.length; column++) {
                        for (int row = 0; row < fractal[0].length; row++) {
                            currentFractal[startingColumnIndex + column][startingRowIndex + row] = fractal[column][row];
                        }

                    }
                }

                // move row forward by one section
                startingRowIndex += fractalLength / 3;
            }
            startingRowIndex = 0;
            // move column down by one section
            startingColumnIndex += fractalLength / 3;
        }

        // base case
        if (currentLevel == level) {
            return currentFractal;
        } else {
            return fillOutFractal(currentLevel + 1, level, n2Fractal, currentFractal);
        }
    }
}

